/// What the spec's case table says a golden report holds. With `only`, the
/// report holds exactly these findings; otherwise at least these, and none
/// with a code in `lacks`.
///
/// A pattern is `CODE`, then optionally `@n` (that seq) or `@-` (no seq),
/// then optionally `:E_…` (that core) or `:file` (that file).
struct Table {
    case: &'static str,
    only: bool,
    has: &'static [&'static str],
    lacks: &'static [&'static str],
}

const fn only(case: &'static str, has: &'static [&'static str]) -> Table {
    Table {
        case,
        only: true,
        has,
        lacks: &[],
    }
}

const fn has(case: &'static str, has: &'static [&'static str]) -> Table {
    Table {
        case,
        only: false,
        has,
        lacks: &[],
    }
}

