/// Whether a finding (as JSON) matches a [`Table`] pattern.
fn matches(pattern: &str, finding: &Value) -> bool {
    let (head, tail) = match pattern.split_once(':') {
        Some((h, t)) => (h, Some(t)),
        None => (pattern, None),
    };
    let (code, seq) = match head.split_once('@') {
        Some((c, s)) => (c, Some(s)),
        None => (head, None),
    };
    let text = |k: &str| finding.get(k).and_then(Value::as_str);
    let seq_ok = match seq {
        None => true,
        Some("-") => finding.get("seq").is_none(),
        Some(n) => finding.get("seq").map(canonicalize).as_deref() == Some(n),
    };
    let tail_ok = match tail {
        None => true,
        Some(t) if t.starts_with("E_") => text("core") == Some(t),
        Some(t) => text("file") == Some(t),
    };
    text("code") == Some(code) && seq_ok && tail_ok
}

/// Problems with a golden report against its row of the case table.
fn table_problems(row: &Table, expect: &Value) -> Vec<String> {
    let findings = expect
        .get("findings")
        .and_then(Value::as_array)
        .unwrap_or(&[]);
    let mut used = vec![false; findings.len()];
    let mut problems = Vec::new();
    for pattern in row.has {
        let hit = (0..findings.len()).find(|&i| !used[i] && matches(pattern, &findings[i]));
        match hit {
            Some(i) => used[i] = true,
            None => problems.push(format!("no finding matches {pattern}")),
        }
    }
    if row.only {
        for (f, used) in findings.iter().zip(&used) {
            if !used {
                problems.push(format!("unexpected finding {}", canonicalize(f)));
            }
        }
    }
    for code in row.lacks {
        if findings
            .iter()
            .any(|f| f.get("code").and_then(Value::as_str) == Some(code))
        {
            problems.push(format!("holds {code}"));
        }
    }
    problems
}

fn export_dir(case: &str) -> PathBuf {
    root().join("exports").join(case)
}

fn read(path: &Path) -> Vec<u8> {
    fs::read(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn parse_file(path: &Path) -> Value {
    json::parse(&read(path)).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

/// `NNNNNN.jsonl`: six or more digits, then `.jsonl`.
fn is_segment_name(name: &str) -> bool {
    name.strip_suffix(".jsonl")
        .is_some_and(|stem| stem.len() >= 6 && stem.bytes().all(|b| b.is_ascii_digit()))
}

/// The export's segment files in file-name order, as the spec's conformance
/// section says a test passes them, read as raw bytes.
fn segment_files(dir: &Path) -> Vec<(String, Vec<u8>)> {
    let mut names: Vec<String> = fs::read_dir(dir)
        .unwrap_or_else(|e| panic!("{}: {e}", dir.display()))
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .filter(|name| is_segment_name(name))
        .collect();
    names.sort();
    names
        .into_iter()
        .map(|name| {
            let bytes = read(&dir.join(&name));
            (name, bytes)
        })
        .collect()
}

/// Verify one export case directory with its case's `max_findings`.
fn verify_case(case: &str) -> (Value, Value) {
    let dir = export_dir(case);
    let spec = parse_file(&dir.join("case.json"));
    let max_findings = match spec.get("max_findings") {
        None => 1000,
        Some(Value::Number(n)) if *n >= 1.0 && n.fract() == 0.0 => *n as usize,
        Some(other) => panic!("{case}: max_findings is {}", canonicalize(other)),
    };
    let manifest = read(&dir.join("manifest.json"));
    let files = segment_files(&dir);
    let segments: Vec<&[u8]> = files.iter().map(|(_, b)| b.as_slice()).collect();
    let report = verify_export(
        &manifest,
        &segments,
        VerifyOptions {
            max_findings,
            ..VerifyOptions::default()
        },
    );
    (spec, report.to_value())
}

fn members(v: &Value) -> Vec<&str> {
    v.as_object()
        .map(|m| m.iter().map(|(k, _)| k.as_str()).collect())
        .unwrap_or_default()
}

#[test]
fn export_vectors() {
    let dir = root().join("exports");
    let mut found: Vec<String> = fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("{}: {e}", dir.display()))
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .collect();
    found.sort();
    for case in CASES {
        assert!(
            found.iter().any(|f| f == case),
            "missing export case {case}"
        );
    }
    assert_eq!(TABLE.len(), CASES.len());

    let mut failures = Vec::new();
    for case in &found {
        let (spec, got) = verify_case(case);
        let mut problems = Vec::new();

        // case.json: description and expect required; max_findings and
        // proofs only where the spec puts them.
        let names = members(&spec);
        for name in &names {
            if !["description", "expect", "max_findings", "proofs"].contains(name) {
                problems.push(format!("case.json has an unknown member {name}"));
            }
        }
        if spec.get("description").and_then(Value::as_str).is_none() {
            problems.push("case.json has no description".to_string());
        }
        if names.contains(&"proofs") != (case.as_str() == "003-attestations-two-checkpoints") {
            problems.push("proofs belong to case 003 only".to_string());
        }
        let Some(expect) = spec.get("expect") else {
            failures.push(format!("{case}: case.json has no expect"));
            continue;
        };

        // The conformance rule: canonical report bytes equal.
        let (got_text, want_text) = (canonicalize(&got), canonicalize(expect));
        if got_text != want_text {
            problems.push(format!(
                "report differs\n    got:  {got_text}\n    want: {want_text}"
            ));
        }

        // Valid cases replay from inputs.json and verify ok; tampered ones
        // have no inputs.json.
        let valid = case.starts_with('0');
        if expect.get("ok") != Some(&Value::Bool(valid)) {
            problems.push(format!("expect.ok should be {valid}"));
        }
        let inputs = export_dir(case).join("inputs.json");
        if valid {
            let v = parse_file(&inputs);
            let mut names = members(&v);
            names.sort_unstable();
            if names != ["clock", "name", "ops", "seed", "segment_size"] {
                problems.push(format!("inputs.json members {names:?}"));
            }
        } else if inputs.exists() {
            problems.push("a tampered case has an inputs.json".to_string());
        }

        // The golden report against the spec's case table.
        match TABLE.iter().find(|row| row.case == case) {
            Some(row) => problems.extend(table_problems(row, expect)),
            None => problems.push("not in the spec's case table".to_string()),
        }

        if !problems.is_empty() {
            failures.push(format!("{case}: {}", problems.join("; ")));
        }
    }
    finish("export", failures, found.len());
}

/// Rules of the case table that name members other than findings.
#[test]
fn export_vectors_follow_the_case_table() {
    let expect = |case: &str| {
        parse_file(&export_dir(case).join("case.json"))
            .get("expect")
            .cloned()
            .unwrap()
    };
    let manifest = |case: &str| parse_file(&export_dir(case).join("manifest.json"));
    let n = |v: Option<&Value>| v.map(canonicalize);

    assert_eq!(
        n(expect("005-fork")
            .get("counts")
            .and_then(|c| c.get("forks")))
        .as_deref(),
        Some("1")
    );
    assert_eq!(
        n(expect("126-prev-list-order")
            .get("counts")
            .and_then(|c| c.get("forks")))
        .as_deref(),
        Some("0")
    );

    // 007: 300 s and 1 ns after received_at and a day after are counted,
    // exactly 300 s after is not.
    assert_eq!(
        n(expect("007-late-claim").get("counts")).as_deref(),
        Some(r#"{"at_after_received":2,"forks":0}"#)
    );

    // 119: the head is the checkpoint's line, nothing is covered, and the
    // unusable witness is not counted.
    let e = expect("119-final-lf-missing");
    assert!(e.get("covered").is_none());
    assert_eq!(
        n(e.get("checked")).as_deref(),
        Some(r#"{"attestations":2,"checkpoints":1,"entries":6,"objects":3}"#)
    );
    let unsigned = e
        .get("findings")
        .and_then(Value::as_array)
        .unwrap()
        .iter()
        .find(|f| f.get("code").and_then(Value::as_str) == Some("S_CHECKPOINT_UNSIGNED"))
        .unwrap()
        .clone();
    assert_eq!(
        n(e.get("head").and_then(|h| h.get("seq"))),
        n(unsigned.get("seq"))
    );

    // 120: the head is seq 2, which the manifest names.
    let e = expect("120-blank-line");
    assert_eq!(
        n(e.get("head").and_then(|h| h.get("seq"))).as_deref(),
        Some("2")
    );

    // 121: no log, no head, nothing counted.
    let e = expect("121-crlf");
    assert!(e.get("log").is_none() && e.get("head").is_none());
    assert_eq!(
        n(e.get("checked")).as_deref(),
        Some(r#"{"attestations":0,"checkpoints":0,"entries":0,"objects":0}"#)
    );

    // 122: the log id of case 002, read from line 2.
    assert_eq!(
        expect("122-first-line-unusable").get("log"),
        manifest("002-records-and-checkpoint").get("log")
    );

    // 128: two checkpoints recognised, and covered is the one of case 002.
    let e = expect("128-checkpoint-recognition");
    assert_eq!(
        n(e.get("checked").and_then(|c| c.get("checkpoints"))).as_deref(),
        Some("2")
    );
    assert_eq!(
        e.get("covered").and_then(|c| c.get("checkpoint")),
        manifest("002-records-and-checkpoint")
            .get("checkpoint")
            .and_then(|c| c.get("id"))
    );

    // 129: the files of 125, with max_findings 2, truncated.
    let case = parse_file(&export_dir("129-findings-truncated").join("case.json"));
    assert_eq!(n(case.get("max_findings")).as_deref(), Some("2"));
    assert_eq!(
        expect("129-findings-truncated").get("truncated"),
        Some(&Value::Bool(true))
    );
    let files = |case: &str| {
        let dir = export_dir(case);
        (read(&dir.join("manifest.json")), segment_files(&dir))
    };
    assert_eq!(
        files("129-findings-truncated"),
        files("125-invalid-object-not-held")
    );

    // 130: the checkpoint has no valid witness, so nothing is covered.
    assert!(expect("130-witness-nonce-zero").get("covered").is_none());

    // 132: the unusable line is not counted, and the head is the last line.
    let e = expect("132-entry-invalid");
    assert_eq!(
        n(e.get("head").and_then(|h| h.get("seq"))).as_deref(),
        Some("4")
    );
    assert_eq!(
        n(e.get("checked").and_then(|c| c.get("entries"))).as_deref(),
        Some("3")
    );
}

/// Case 003's proofs: each one verifies, and the Rust crate produces each one
/// byte for byte from the export's lines.
#[test]
fn export_proofs() {
    let dir = export_dir("003-attestations-two-checkpoints");
    let spec = parse_file(&dir.join("case.json"));
    let proofs = spec.get("proofs").expect("case 003 has proofs");
    let files = segment_files(&dir);

    // The leaves, from the lines; the checkpoints, from the verifier.
    let mut leaves: Vec<Digest> = Vec::new();
    let mut verifier = Verifier::new(VerifyOptions::default());
    for (_, bytes) in &files {
        for line in bytes.split(|&b| b == b'\n').filter(|l| !l.is_empty()) {
            let parsed = parse_line(line).expect("a valid line");
            leaves.push(merkle::leaf_hash(parsed.entry_canonical.as_bytes()));
        }
        verifier.push_segment(bytes);
    }
    let checkpoints: Vec<(u64, String)> = verifier
        .checkpoints()
        .iter()
        .map(|(_, _, c)| (c.size, c.root.clone()))
        .collect();
    assert_eq!(checkpoints.len(), 2, "case 003 has two checkpoints");
    assert!(verifier.finish().ok());
    let (old_size, old_root) = &checkpoints[0];
    let (size, root) = &checkpoints[1];

    let inclusion = list(proofs, "inclusion");
    assert_eq!(inclusion.len() as u64, *size, "one inclusion proof per seq");
    let mut failures = Vec::new();
    for (i, p) in inclusion.iter().enumerate() {
        let seq = u(p, "seq");
        let index = seq - 1;
        let proof = digests(p, "proof");
        let mut problems = Vec::new();
        if seq != i as u64 + 1 || u(p, "size") != *size || s(p, "root") != root {
            problems.push("not in seq order against the latest checkpoint".to_string());
        }
        let leaf = digest(s(p, "leaf_hash"));
        if leaves.get(index as usize) != Some(&leaf) {
            problems.push("leaf_hash is not the leaf hash of the entry".to_string());
        }
        if merkle::inclusion_proof(&leaves[..*size as usize], index) != proof {
            problems.push("proof differs from the one Rust produces".to_string());
        }
        if !merkle::verify_inclusion(&leaf, index, *size, &proof, &digest(root)) {
            problems.push("does not verify".to_string());
        }
        if !problems.is_empty() {
            failures.push(format!("inclusion seq {seq}: {}", problems.join("; ")));
        }
    }

    let consistency = list(proofs, "consistency");
    assert_eq!(consistency.len(), 1, "one consistency proof");
    let p = &consistency[0];
    let proof = digests(p, "proof");
    let mut problems = Vec::new();
    if u(p, "old_size") != *old_size
        || u(p, "new_size") != *size
        || s(p, "old_root") != old_root
        || s(p, "new_root") != root
    {
        problems.push("not from the first checkpoint to the second".to_string());
    }
    if merkle::consistency_proof(&leaves[..*size as usize], *old_size) != proof {
        problems.push("proof differs from the one Rust produces".to_string());
    }
    if !merkle::verify_consistency(*old_size, *size, &digest(old_root), &digest(root), &proof) {
        problems.push("does not verify".to_string());
    }
    if !problems.is_empty() {
        failures.push(format!("consistency: {}", problems.join("; ")));
    }
    finish("proof", failures, inclusion.len() + 1);
}
